export function normalizeLanguage(value) { return SUPPORTED_LANGUAGES.includes(value) ? value : DEFAULT_LANGUAGE; }

export function translate(language, key, params = {}) {
  const normalized = normalizeLanguage(language);
  const template = catalogs[normalized][key] ?? catalogs.zh[key] ?? key;
  return String(template).replace(/\{([a-zA-Z0-9_]+)\}/g, (match, name) => Object.hasOwn(params, name) ? String(params[name]) : match);
}

export function readLanguage(storage = globalThis.localStorage) {
  try { return normalizeLanguage(storage?.getItem(LANGUAGE_STORAGE_KEY)); } catch { return DEFAULT_LANGUAGE; }
}

export function writeLanguage(language, storage = globalThis.localStorage) {
  try { storage?.setItem(LANGUAGE_STORAGE_KEY, normalizeLanguage(language)); return true; } catch { return false; }
}

export function getOrganizerMessages(language) { return Object.fromEntries(organizerKeys.map(key => [key, translate(language, `organizer.${key}`)])); }
export function getStateLabel(language, state) { return translate(language, `run.state.${state}`); }
export function getProfileName(language, profile) { return catalogs[normalizeLanguage(language)][`profile.${profile.id}`] || profile.name; }
export function getExampleCopy(language, example) {
  const prefix = `example.${example.id}`;
  const catalog = catalogs[normalizeLanguage(language)];
  return { ...example, name: catalog[`${prefix}.name`] || example.name, topic: catalog[`${prefix}.topic`] || example.topic, description: catalog[`${prefix}.description`] || example.description };
}

export function localizeError(language, error) {
  const key = errorKeys[error?.code];
  if (key) return translate(language, key);
  if (normalizeLanguage(language) === 'en' && !error?.message) return 'The request failed.';
  return error?.message || translate(language, 'error.INVALID_RESPONSE');
}

export function localizeServerMessage(language, message) {
  if (!message || normalizeLanguage(language) === 'zh') return message || '';
  if (serverMessages[message]) return serverMessages[message];
  const exitCode = /^程序退出码：(\d+)$/.exec(message);
  return exitCode ? `Program exit code: ${exitCode[1]}` : message;
}
